use rig::Embed;


#[derive(Embed)]
struct WordDefinition {
    id: String,
    word: String,
    #[embed]
    definitions: Vec<String>,
}

use rig::embeddings::{Embed, EmbedError, TextEmbedder};


struct WordDefinition {
    id: String,
    word: String,
    definition: String,
}


impl Embed for WordDefinition {
    fn embed(&self, embedder: &mut TextEmbedder) -> Result<(), EmbedError> {
        // Embed the word together with its definition.
        embedder.embed(format!("{}: {}", self.word, self.definition));
        Ok(())
    }
}

#[derive(rig::Embed, serde::Serialize, Clone)]
struct Doc {
    id: String,
    #[embed]
    text: String,
}


let documents = vec![
    Doc { id: "doc0".into(), text: "Rig is a Rust library for LLM apps.".into() },
    Doc { id: "doc1".into(), text: "Embeddings map text to vectors.".into() },
];


let model = OpenAI::from_env()?.embedding(openai::TEXT_EMBEDDING_3_SMALL, None);


let embeddings = EmbeddingsBuilder::new(model)
    .documents(documents)?
    .build()
    .await?;

// In memory, keyed by generated ids ("doc0", "doc1", ...).
let store = InMemoryVectorStore::from_documents(embeddings);


// Turn the store into a searchable index with the same embedding model.
let index = store.index(model);

use rig::vector_store::{InsertDocuments, VectorStoreError};
use rig::embeddings::{Embed, Embedding};
use serde::Serialize;

async fn insert<S, D>(store: &S, embeddings: Vec<(D, Vec<Embedding>)>) -> Result<(), VectorStoreError>
where
    S: InsertDocuments,
    D: Serialize + Embed + Send,
{
    store.insert_documents(embeddings).await
}
